const $=s=>document.querySelector(s);const steps=['Service','Project','Setup','Delivery','Review'];const initial={step:0,service:'Video',project:'',people:2,cameras:2,hours:4,location:'Windhoek',date:'',extras:[],name:'',email:''};let state={...initial};try{const saved=JSON.parse(localStorage.getItem('vh-draft'));if(saved&&saved.step<5)state={...initial,...saved}}catch{}const money=n=>'N$ '+n.toLocaleString('en-NA');const projects={Video:['Podcast','Social reel','Music video','Event recap','Interview','Commercial'],Photo:['Portraits','Headshots','Event photography','Product photography'], 'Photo + video':['Event coverage','Brand content','Conference'],Editing:['Social reel edit','Podcast edit','Music video edit','Commercial edit']};
function art(type){let body=type==='Video'?'<rect x="40" y="34" width="104" height="65" rx="9" fill="#343c34"/><rect x="48" y="40" width="40" height="12" rx="3" fill="#535d4e"/><circle cx="125" cy="68" r="37" fill="#717d65"/><circle cx="125" cy="68" r="29" fill="#262f29"/><circle cx="125" cy="68" r="20" fill="#465642"/><circle cx="125" cy="68" r="10" fill="#1f2723"/><path d="M58 34v-9h48v9" fill="none" stroke="#343c34" stroke-width="8"/><circle cx="60" cy="66" r="5" fill="#d8ee83"/>':type==='Photo'?'<path d="M50 40h25l10-13h40l10 13h20v62H50z" fill="#444b40"/><circle cx="104" cy="71" r="30" fill="#8a917c"/><circle cx="104" cy="71" r="23" fill="#29332b"/><circle cx="104" cy="71" r="13" fill="#596a50"/><rect x="137" y="47" width="10" height="6" fill="#d8ee83"/>':type==='Editing'?'<rect x="35" y="24" width="140" height="82" rx="5" fill="#3b463e"/><rect x="43" y="32" width="124" height="48" rx="2" fill="#9ba58e"/><path d="m97 43 22 13-22 13z" fill="#e1e7d7"/><path d="M45 91h32m7 0h45m7 0h28" stroke="#d8ee83" stroke-width="6"/><path d="M95 107v12m-20 0h60" stroke="#3b463e" stroke-width="6"/>':'<rect x="34" y="45" width="100" height="65" rx="6" fill="#48594e"/><circle cx="85" cy="77" r="24" fill="#9aa98e"/><circle cx="85" cy="77" r="16" fill="#2b3b31"/><rect x="112" y="20" width="55" height="75" rx="5" fill="#73816d"/><circle cx="139" cy="56" r="17" fill="#2b3b31"/><circle cx="139" cy="56" r="10" fill="#b6c5a3"/><path d="M45 46v-8h34v8" stroke="#48594e" stroke-width="5"/>';return `<svg viewBox="0 0 210 135" aria-hidden="true"><ellipse cx="107" cy="120" rx="73" ry="5" fill="#000" opacity=".06"/>${body}</svg>`}
function estimate(){if(!state.project)return [];const isEdit=state.service==='Editing';let lines=[{label:isEdit?'Editing base':'Production base',value:isEdit?2000:4500}];if(!isEdit){lines.push({label:`${state.hours} hours coverage`,value:state.hours*500});if(state.cameras>1)lines.push({label:`${state.cameras-1} extra camera kit${state.cameras>2?'s':''}`,value:(state.cameras-1)*1200});if(state.project==='Podcast')lines.push({label:`Audio · ${state.people} people`,value:state.people*250})}lines.push({label:'Main edit',value:1500});for(const id of state.extras){const e=extras.find(x=>x.id===id);if(e)lines.push({label:e.title,value:e.price})}return lines}
const extras=[{id:'clips',title:'3 social cutdowns',sub:'Short vertical edits from your shoot',price:1200},{id:'captions',title:'Captions',sub:'Readable, styled subtitles',price:450},{id:'rush',title:'Priority delivery',sub:'Subject to schedule confirmation',price:1500}];
function save(){try{localStorage.setItem('vh-draft',JSON.stringify(state))}catch{}}function select(key,value){state[key]=value;if(key==='service'){state.project='';state.extras=[];state.cameras=value==='Photo'?1:2}save();render()}function row(title,sub,selected,action){return `<button class="option ${selected?'selected':''}" ${action} aria-pressed="${selected}"><span><strong>${title}</strong>${sub?`<small>${sub}</small>`:''}</span><span class="check">${selected?'✓':''}</span></button>`}function segment(key,values){return `<div class="segments">${values.map(v=>`<button data-key="${key}" data-value="${v}" class="${state[key]===v?'selected':''}" aria-pressed="${state[key]===v}">${v}${key==='hours'?' hrs':''}</button>`).join('')}</div>`}function heading(k,title,sub){return `${state.step>0?'<button class="back" id="back">← Back</button>':''}<p class="eyebrow">${k}</p><h1>${title}</h1><p class="intro">${sub}</p>`}
function render(){save();$('.steps').innerHTML=steps.map((s,i)=>`<button data-step="${i}" class="${i===state.step?'active':''}" ${i>state.step?'disabled':''} ${i===state.step?'aria-current="step"':''}><b>${i<state.step?'✓':String(i+1).padStart(2,'0')}</b>${s}</button>`).join('');let html='';switch(state.step){case 0:html=heading('LET’S MAKE SOMETHING','What are we<br>creating?','Pick a starting point. We’ll work out the setup together.')+`<div class="service-grid">${['Video','Photo','Photo + video','Editing'].map((s,i)=>`<button class="service ${state.service===s?'selected':''}" data-key="service" data-value="${s}" aria-pressed="${state.service===s}"><div class="art">${art(s)}</div><span class="label"><span>${s}<small>${['Motion, stories & sound','People, products & moments','The complete picture','Bring your footage to life'][i]}</small></span><span class="arrow">${state.service===s?'✓':'↗'}</span></span></button>`).join('')}</div><p class="note">Windhoek based. Available wherever your story takes us.</p>`;break;case 1:html=heading('CHOOSE YOUR PROJECT','What’s the occasion?','Choose the closest fit. You can adjust the details next.')+`<div class="rows">${projects[state.service].map(s=>row(s,'',state.project===s,`data-key="project" data-value="${s}"`)).join('')}</div>`;break;case 2:html=heading('YOUR PRODUCTION','Let’s set the scene.','A few details to shape your shoot.')+`${state.project==='Podcast'?`<div class="field-group"><label class="field-label">People on camera</label>${segment('people',[1,2,3,4])}</div>`:''}${state.service!=='Editing'?`<div class="field-group"><label class="field-label">Camera angles</label>${segment('cameras',[1,2,3])}</div><div class="field-group"><label class="field-label">Coverage time</label>${segment('hours',[2,4,8])}</div><div class="setup-info">${state.cameras} camera kit${state.cameras>1?'s':''} with support. Lighting and crew confirmed after review.${state.project==='Podcast'?` Audio for ${state.people} people.`:''}</div>`:'<div class="setup-info">We’ll confirm footage volume and editing complexity before quoting.</div>'}<div class="field-grid"><label><small>Preferred date · optional</small><input type="date" id="date" value="${escapeText(state.date)}" min="${new Date().toLocaleDateString('en-CA')}"></label><label><small>Location</small><select id="location">${['Windhoek','Swakopmund','Walvis Bay','Other / remote'].map(x=>`<option ${state.location===x?'selected':''}>${x}</option>`).join('')}</select></label></div>`;break;case 3:html=heading('THE FINAL CUT','Make it yours.','A main edit is included. Add what you need.')+`<div class="rows">${extras.map(e=>row(e.title,`${e.sub} · +${money(e.price)}`,state.extras.includes(e.id),`data-extra="${e.id}"`)).join('')}</div><p class="note">Final edit length and delivery date are confirmed in your quotation.</p>`;break;case 4:html=heading('ONE LAST LOOK','Your shoot,<br>at a glance.','Check your plan, then leave your details.')+`<div class="review-row"><span>${escapeText(state.project)}<br><small>${escapeText(state.service)}</small></span><button data-step="1">Edit</button></div><div class="review-row"><span>${state.cameras} angles · ${state.hours} hours<br><small>${escapeText(state.location)} · ${state.date||'Date flexible'}</small></span><button data-step="2">Edit</button></div><form id="contact"><div class="field-grid"><label><small>Your name</small><input id="name" autocomplete="name" required maxlength="100" value="${escapeText(state.name)}"></label><label><small>Email address</small><input id="email" type="email" autocomplete="email" required value="${escapeText(state.email)}"></label></div></form><div class="preview-note">Design preview. Prices are illustrative, not your published rate card. This demo saves on this device only. No email or quotation will be sent.</div>`;break;case 5:html=`<div class="success-mark">✓</div><p class="eyebrow">DEMO COMPLETE</p><h1>That’s your<br>shoot planned.</h1><p class="intro">Your demo brief is saved on this device.</p><div class="setup-info">Nothing has been sent. The live version will send your request to VisionHaus for a formal quotation.</div><button class="text-btn" id="download">Download demo brief ↗</button>`}$('#content').innerHTML=html;const lines=estimate(),total=lines.reduce((s,x)=>s+x.value,0);$('#summary').innerHTML=`<div class="aside-title">YOUR SHOOT <span><i class="live-dot"></i>LIVE ESTIMATE</span></div><div class="summary-name">${escapeText(state.project||'A little possibility.')}</div><div class="summary-sub">${state.project?`${state.service} · ${escapeText(state.location)}`:'Your plan takes shape here.<br>Start with what you want to create.'}</div><div class="summary-lines">${lines.length?lines.map(l=>`<div class="summary-line"><span>${l.label}</span><span>${money(l.value)}</span></div>`).join(''):'<div class="summary-line"><span>Choose your project</span><span>—</span></div>'}</div><div class="total"><small>ESTIMATED TOTAL · EX VAT</small><strong>${total?money(total):'Scope first.'}</strong></div><p class="mini-note">${total?'Illustrative pricing for this preview. Travel and custom production costs require review.':'No account needed.<br>No commitment at this stage.'}</p><div class="preview-note">Built around your shoot.<br>Final scope and availability confirmed by VisionHaus.</div>`;$('#mobile-price').textContent=total?money(total):'Scope first';$('#next').innerHTML=["Build my shoot <span>↗</span>","Set up my shoot <span>↗</span>","Choose delivery <span>↗</span>","Review my plan <span>↗</span>","Save demo brief <span>↗</span>","Start a new plan <span>↗</span>"][state.step];$('#next').disabled=state.step===1&&!state.project;document.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>select(b.dataset.key,['people','hours','cameras'].includes(b.dataset.key)?Number(b.dataset.value):b.dataset.value));document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{state.step=Number(b.dataset.step);render();scrollTo(0,0)});document.querySelectorAll('[data-extra]').forEach(b=>b.onclick=()=>{const id=b.dataset.extra;state.extras=state.extras.includes(id)?state.extras.filter(x=>x!==id):[...state.extras,id];render()});if($('#back'))$('#back').onclick=()=>{state.step--;render();scrollTo(0,0)};for(const id of ['date','location','name','email'])if($('#'+id))$('#'+id).oninput=e=>{state[id]=e.target.value;save()};if($('#download'))$('#download').onclick=()=>{const blob=new Blob([JSON.stringify({notice:'Demo only. Not submitted. Illustrative prices.',brief:state,estimate:lines,total},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='visionhaus-demo-brief.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}}
function escapeText(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}$('#next').onclick=()=>{if(state.step===4&&!$('#contact').reportValidity())return;if(state.step===5)state={...initial,extras:[]};else state.step++;render();scrollTo({top:0,behavior:'smooth'})};$('#reset').onclick=()=>{if(confirm('Clear this draft and start again?')){state={...initial,extras:[]};render();scrollTo(0,0)}};render();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});

function toggleSummary(){if(matchMedia('(max-width:700px)').matches){const open=$('#summary').classList.toggle('mobile-open');$('#estimate-toggle').setAttribute('aria-expanded',String(open))}}$('#estimate-toggle').onclick=toggleSummary;$('#estimate-toggle').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggleSummary()}};
